import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.DZhUhjDB.js";const p=JSON.parse('{"title":"🌐 Seguridad de Redes","description":"🌐 Seguridad de Redes","frontmatter":{"title":"🌐 Seguridad de Redes","description":"🌐 Seguridad de Redes"},"headers":[],"relativePath":"roles/blue-team/seguridad-redes.md","filePath":"roles/blue-team/seguridad-redes.md","lastUpdated":1787321037000}'),d={name:"roles/blue-team/seguridad-redes.md"};function i(o,e,n,l,c,u){return a(),s("div",null,[...e[0]||(e[0]=[r(`<div align="center"><h1 id="🌐-seguridad-de-redes" tabindex="-1">🌐 Seguridad de Redes <a class="header-anchor" href="#🌐-seguridad-de-redes" aria-label="Permalink to &quot;🌐 Seguridad de Redes&quot;">​</a></h1><p><strong>CISSP Domain · Network Security</strong></p><p><em>&quot;El perímetro ya no existe — pero la red sigue siendo el campo de batalla.&quot;</em></p><p><img src="https://img.shields.io/badge/tier%20salarial-B-blue" alt="Tier"> <img src="https://img.shields.io/badge/demanda-alta-green" alt="Demanda"> <img src="https://img.shields.io/badge/entry%20level-amigable-success" alt="Entry"></p></div><hr><h2 id="📋-descripcion" tabindex="-1">📋 Descripción <a class="header-anchor" href="#📋-descripcion" aria-label="Permalink to &quot;📋 Descripción&quot;">​</a></h2><p>Disciplina enfocada en <strong>proteger la infraestructura de red</strong> — desde el datacenter clásico hasta arquitecturas Zero Trust modernas. Cubre diseño seguro, segmentación, detección de tráfico malicioso, control de acceso y respuesta a incidentes de red.</p><p>Es una de las ramas de entrada más sólidas a ciberseguridad porque conecta directamente con la base de cualquier sysadmin: TCP/IP, routing, firewalls, VPN. La evolución 2024-2026 está empujando hacia <strong>SASE, ZTNA y microsegmentación</strong>, dejando atrás el modelo de &quot;castillo y foso&quot;.</p><hr><h2 id="👤-roles-tipicos" tabindex="-1">👤 Roles típicos <a class="header-anchor" href="#👤-roles-tipicos" aria-label="Permalink to &quot;👤 Roles típicos&quot;">​</a></h2><ul><li><strong>Network Security Engineer</strong> — diseña, implementa y mantiene firewalls, IDS/IPS, VPN</li><li><strong>Firewall Administrator</strong> — gestión BAU de reglas, change management, auditoría</li><li><strong>SOC Tier 2 Network</strong> — investigación de alertas de tráfico (IDS/IPS, NetFlow)</li><li><strong>Zero Trust Architect</strong> <em>(senior)</em> — diseño de arquitecturas ZTNA/SASE</li><li><strong>NOC/SecOps Hybrid</strong> — entornos pequeños donde se combinan funciones</li></ul><hr><h2 id="🛠️-stack-y-herramientas" tabindex="-1">🛠️ Stack y herramientas <a class="header-anchor" href="#🛠️-stack-y-herramientas" aria-label="Permalink to &quot;🛠️ Stack y herramientas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Herramientas</th></tr></thead><tbody><tr><td><strong>Firewalls (NGFW)</strong></td><td>Palo Alto · Fortinet FortiGate · Cisco Firepower · pfSense · OPNsense · Check Point</td></tr><tr><td><strong>IDS/IPS</strong></td><td>Suricata · Snort · Zeek (antes Bro) · Cisco Stealthwatch</td></tr><tr><td><strong>VPN / ZTNA</strong></td><td>OpenVPN · WireGuard · Cisco AnyConnect · Cloudflare Access · Tailscale · Twingate</td></tr><tr><td><strong>NAC</strong></td><td>Cisco ISE · Aruba ClearPass · FortiNAC · packetfence</td></tr><tr><td><strong>Análisis de tráfico</strong></td><td>Wireshark · tshark · tcpdump · nfdump · Arkime (Moloch)</td></tr><tr><td><strong>Pentest red</strong></td><td>Nmap · Masscan · Responder · MITM6 · Bettercap</td></tr><tr><td><strong>Segmentación</strong></td><td>VLANs · 802.1X · VXLAN · Calico (k8s) · Illumio · Guardicore</td></tr></tbody></table><hr><h2 id="🎓-certificaciones-recomendadas" tabindex="-1">🎓 Certificaciones recomendadas <a class="header-anchor" href="#🎓-certificaciones-recomendadas" aria-label="Permalink to &quot;🎓 Certificaciones recomendadas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Certificación</th><th>Vendor</th><th>Costo (USD)</th><th>Notas</th></tr></thead><tbody><tr><td>Entry</td><td>CompTIA Network+</td><td>CompTIA</td><td>~$370</td><td>Base obligatoria si no vienes de redes</td></tr><tr><td>Entry</td><td>CompTIA Security+</td><td>CompTIA</td><td>~$400</td><td>Pareja del Network+</td></tr><tr><td>Mid</td><td>CCNA Security <em>(legacy)</em> / CCNP Security</td><td>Cisco</td><td>~$300-600</td><td>Estándar enterprise</td></tr><tr><td>Mid</td><td>Fortinet NSE 4-5</td><td>Fortinet</td><td>~$400</td><td>Muy demandado en LATAM</td></tr><tr><td>Mid</td><td>Palo Alto PCNSA → PCNSE</td><td>Palo Alto</td><td>~$200-400</td><td>Top tier en mercado</td></tr><tr><td>Senior</td><td>CISSP</td><td>(ISC)²</td><td>~$750</td><td>Exige 5 años de experiencia</td></tr><tr><td>Senior</td><td>GIAC GCIA / GCNF</td><td>SANS</td><td>~$2,500+</td><td>Análisis profundo de red</td></tr></tbody></table><hr><h2 id="🗺️-roadmap-12-meses" tabindex="-1">🗺️ Roadmap (12 meses) <a class="header-anchor" href="#🗺️-roadmap-12-meses" aria-label="Permalink to &quot;🗺️ Roadmap (12 meses)&quot;">​</a></h2><h3 id="fase-1-—-fundamentos-0-3-meses" tabindex="-1">Fase 1 — Fundamentos (0-3 meses) <a class="header-anchor" href="#fase-1-—-fundamentos-0-3-meses" aria-label="Permalink to &quot;Fase 1 — Fundamentos (0-3 meses)&quot;">​</a></h3><ul><li>[ ] CCNA o equivalente: subnetting, routing, VLANs, ACLs</li><li>[ ] Lab con pfSense + Suricata en VirtualBox</li><li>[ ] Wireshark a nivel de captura y filtrado</li><li>[ ] Network+ o Security+ aprobado</li></ul><h3 id="fase-2-—-especializacion-3-6-meses" tabindex="-1">Fase 2 — Especialización (3-6 meses) <a class="header-anchor" href="#fase-2-—-especializacion-3-6-meses" aria-label="Permalink to &quot;Fase 2 — Especialización (3-6 meses)&quot;">​</a></h3><ul><li>[ ] FortiGate o Palo Alto en modo lab (versión eval)</li><li>[ ] OpenVPN + WireGuard montados desde cero</li><li>[ ] Detección de túneles DNS / C2 con Suricata + reglas ET Open</li><li>[ ] Documentar 3 incidentes de red en <code>casos-uso/</code></li></ul><h3 id="fase-3-—-profesional-6-12-meses" tabindex="-1">Fase 3 — Profesional (6-12 meses) <a class="header-anchor" href="#fase-3-—-profesional-6-12-meses" aria-label="Permalink to &quot;Fase 3 — Profesional (6-12 meses)&quot;">​</a></h3><ul><li>[ ] Diseño de arquitectura segmentada (DMZ + zonas internas + ZTNA)</li><li>[ ] Cisco ISE / Aruba ClearPass para 802.1X</li><li>[ ] PCNSA o NSE 4 aprobado</li><li>[ ] Caso real: deploy ZTNA en pyme (Cloudflare Access / Twingate)</li></ul><hr><h2 id="💰-salarios-en-colombia-usd-mes" tabindex="-1">💰 Salarios en Colombia (USD/mes) <a class="header-anchor" href="#💰-salarios-en-colombia-usd-mes" aria-label="Permalink to &quot;💰 Salarios en Colombia (USD/mes)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Local 🇨🇴</th><th>Remoto 🌎</th><th>Notas</th></tr></thead><tbody><tr><td>Junior (0-2 años)</td><td>$700 - $1,300</td><td>$1,200 - $2,200</td><td>Mercado bancario y telco</td></tr><tr><td>Mid (2-5 años)</td><td>$1,700 - $3,200</td><td>$3,000 - $5,500</td><td>NGFW + ZTNA aumenta el rango</td></tr><tr><td>Senior (5+ años)</td><td>$4,000 - $7,500</td><td>$6,000 - $11,000</td><td>Architect ZT/SASE = top de banda</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> los certificados Fortinet/Palo Alto pesan más que el título universitario en LATAM.</p></blockquote><hr><h2 id="🔗-conexion-con-otras-ramas" tabindex="-1">🔗 Conexión con otras ramas <a class="header-anchor" href="#🔗-conexion-con-otras-ramas" aria-label="Permalink to &quot;🔗 Conexión con otras ramas&quot;">​</a></h2><ul><li><strong><code>arquitecto-seguridad</code></strong> → la red es la base del diseño Zero Trust</li><li><strong><code>seguridad-nube</code></strong> → VPC, peering, transit gateway, CloudFront, security groups</li><li><strong><code>threat-hunter</code></strong> → NetFlow + Zeek son sus mejores amigos</li><li><strong><code>incident-responder</code></strong> → contención de red en primera línea</li><li><strong><code>seguridad-defensiva-blue-team</code></strong> → Suricata + Wazuh + Zeek = stack defensivo</li></ul><hr><h2 id="📂-estructura" tabindex="-1">📂 Estructura <a class="header-anchor" href="#📂-estructura" aria-label="Permalink to &quot;📂 Estructura&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>seguridad-redes/</span></span>
<span class="line"><span>├── herramientas/    # Configs de pfSense, Suricata, FortiGate, etc.</span></span>
<span class="line"><span>├── recursos/        # Cheatsheets, papers, RFCs clave</span></span>
<span class="line"><span>├── laboratorios/    # Labs reproducibles (compose con red aislada)</span></span>
<span class="line"><span>└── casos-uso/       # Detección de C2, exfiltración DNS, MITM, etc.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><div align="center"><p><strong><a href="./../README">⬅ Volver a Ciberseguridad</a></strong></p></div>`,34)])])}const h=t(d,[["render",i]]);export{p as __pageData,h as default};
